using BmsDesktop.Infrastructure;
using Npgsql;
namespace BmsDesktop.Production;
public sealed class ProductionDetailService { private readonly Database _db; public ProductionDetailService(Database db)=>_db=db; public async Task AddFeedAsync(Guid cycle,DateOnly date,Guid? item,decimal kg,bool extra,string notes){if(kg<0)throw new ArgumentException("Jumlah pakan tidak valid.");await using var cn=await _db.OpenAsync();await using var c=new NpgsqlCommand("insert into feed_usage(id,cycle_id,usage_date,item_id,quantity_kg,source,notes) values(@id,@c,@d,@i,@q,@s,@n)",cn);c.Parameters.AddWithValue("id",Guid.NewGuid());c.Parameters.AddWithValue("c",cycle);c.Parameters.AddWithValue("d",date.ToDateTime(TimeOnly.MinValue));c.Parameters.AddWithValue("i",(object?)item??DBNull.Value);c.Parameters.AddWithValue("q",kg);c.Parameters.AddWithValue("s",extra?"EXTRA":"CONTRACT");c.Parameters.AddWithValue("n",notes??"");await c.ExecuteNonQueryAsync();} public async Task AddAbkAsync(Guid cycle,DateOnly date,string worker,string type,decimal qty,decimal rate,string notes){if(qty<0||rate<0)throw new ArgumentException("Data ABK tidak valid.");await using var cn=await _db.OpenAsync();await using var c=new NpgsqlCommand("insert into abk_work_entries(id,cycle_id,work_date,worker_name,work_type,quantity,rate,notes) values(@id,@c,@d,@w,@t,@q,@r,@n)",cn);c.Parameters.AddWithValue("id",Guid.NewGuid());c.Parameters.AddWithValue("c",cycle);c.Parameters.AddWithValue("d",date.ToDateTime(TimeOnly.MinValue));c.Parameters.AddWithValue("w",worker);c.Parameters.AddWithValue("t",type);c.Parameters.AddWithValue("q",qty);c.Parameters.AddWithValue("r",rate);c.Parameters.AddWithValue("n",notes??"");await c.ExecuteNonQueryAsync();} }
